        {
            e = e || window.event;

            if (self.isVisible()) {

                switch(e.keyCode){
                    case 13:
                    case 27:
                        if (opts.field) {
                            opts.field.blur();
                        }
                        break;
                    case 37:
                        e.preventDefault();
                        self.adjustDate('subtract', 1);
                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                }
            }
        };",
      "after":"        self._onKeyChange = function(e)
        {
            e = e || window.event;

            if (self.isVisible() && opts.field && e.target === opts.field) {

                switch(e.keyCode){
                    case 13:
                    case 27:
                        if (opts.field) {
                            opts.field.blur();
                        }
                        break;
                    case 37:
                        e.preventDefault();
                        self.adjustDate('subtract', 1);
                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                }
            }
        };"
    }
  ],
  "expected_accessibility_effect": "ArrowLeft will now move the caret in the notes input, allowing users to insert a space and correct text as intended.",
  "functional_risks": [
    "ArrowUp/Down/Left/Right navigation within the datepicker will no longer work when focus is not on the delivery-date field (e.g., after clicking the calendar).",
    "If the datepicker is opened via programmatic means without focusing its field, arrow keys will be inert."
  ],
  "verification_requirements": [
    "Verify that typing 'Gate4', pressing ArrowLeft, then Space results in notes value 'Gate 4'.",
    "Verify that when the delivery-date field is focused, ArrowLeft/Right/Up/Down still change the selected date in the datepicker.",
    "Verify that Enter and Esc still close the datepicker and blur the field when it is focused.",
    "Verify that no JavaScript errors are thrown in the console during these interactions."
  ]
}

